const testC: ZimmButtonProps = {
  label: 'x',
  variant: 'icon',
  icon: 'arrow-down',
  role: 'checkbox',
  ariaChecked: true,
};

// TEST_D: role + ariaChecked together but on variant="social"
const testD: ZimmButtonProps = {
  label: 'x',
  variant: 'social',
  icon: null,
  role: 'checkbox',
  ariaChecked: true,
};

// TEST_E: role with invalid literal value (not checkbox/radio), no ariaChecked
const testE: ZimmButtonProps = { label: 'x', role: 'tab' };

// TEST_F: valid — role+ariaChecked together on label variant (should be OK, no error expected)
const testF: ZimmButtonProps = { label: 'x', variant: 'secondary', role: 'checkbox', ariaChecked: true };

// TEST_G: valid — no role, no ariaChecked at all on label variant (should be OK)
const testG: ZimmButtonProps = { label: 'x', variant: 'primary' };

export { testA, testB, testC, testD, testE, testF, testG };

