import React from 'react';
import { Box, Checkbox, Flex, Text } from '@chakra-ui/react';
import { useIntl } from 'react-intl';
import { ADD_FILTER, REMOVE_FILTER } from 'app/utils/refinementValues';

export type ZimmCheckboxProps = {
  value: string;
  label: string;
  isChecked: boolean;
  onChange: (value: string, isCurrentlySelected: boolean) => void;
  /** When 0 and not selected the option is hidden — pass undefined to always show. */
  hitCount?: number;
  /** Renders a filled colour dot beside the label when set (e.g. a CSS colour string). */
  swatchColour?: string;
};

/**
 * Single branded checkbox row with optional colour swatch. Handles its own
 * hit-count visibility guard and aria-label state (Add / Remove filter).
 *
 * For lists of options, compose via `ZimmCheckboxGroup`.
 */
export const ZimmCheckbox = ({ value, label, isChecked, onChange, hitCount, swatchColour }: ZimmCheckboxProps) => {
  const intl = useIntl();

  if (hitCount === 0 && !isChecked) return null;

  return (
    <Checkbox
      isChecked={isChecked}
      onChange={() => onChange(value, isChecked)}
      aria-label={intl.formatMessage(isChecked ? REMOVE_FILTER : ADD_FILTER, { label })}
      spacing="var(--zimm-scale-s)"
      sx={{
        '.chakra-checkbox__control': {
          borderColor: 'var(--zimm-color-border-default)',
          _checked: {
            background: 'var(--zimm-color-action-primary-bg-default)',
            borderColor: 'var(--zimm-color-action-primary-bg-default)',
            color: 'var(--zimm-color-action-primary-text)',
          },
          // Brand focus ring — dropping the indicator fails WCAG 2.2 AA SC 2.4.7.
          _focusVisible: {
            outline: 'var(--zimm-focus-ring)',
            outlineOffset: 0,
            boxShadow: 'none',
          },
        },
      }}
    >
      <Flex align="center" gap="var(--zimm-scale-s)">
        {swatchColour !== undefined && (
          <Box
            data-testid="zimm-colour-swatch"
            boxSize="var(--zimm-icon-size-md)"
            borderRadius="full"
            border="var(--zimm-border-width-default) solid var(--zimm-color-border-default)"
            flexShrink={0}
            background={swatchColour || 'transparent'}
          />
        )}
        <Text as="span" textStyle="navigation">
          {label}
        </Text>
      </Flex>
    </Checkbox>
  );
};

=== zimmCheckboxGroup/index.tsx ===
import React from 'react';
import { Stack } from '@chakra-ui/react';
import { ZimmCheckbox } from 'app/components/ui-kits/atoms/zimmCheckbox';

export type ZimmCheckboxGroupOption = {
  value: string;
  label: string;
  /** When 0 and not selected the option is hidden — pass undefined to always show. */
  hitCount?: number;
  /** Renders a filled colour dot beside the label when set (e.g. a CSS colour string). */
  swatchColour?: string;
};

type ZimmCheckboxGroupProps = {
  options: readonly ZimmCheckboxGroupOption[];
  selectedValues: readonly string[];
  /** Called with the option value and whether it was already selected (true = deselect). */
  onChange: (value: string, isCurrentlySelected: boolean) => void;
};

/**
 * Generic checkbox list for multi-select filtering. Not tied to SFCC or any specific data
 * shape — accepts plain option objects so it can be used in filter drawers, preference forms,
 * or any multi-select surface.
 *
 * Each row is a `ZimmCheckbox` atom; hit-count visibility and swatch rendering are
 * delegated there.
 */
export const ZimmCheckboxGroup = ({ options, selectedValues, onChange }: ZimmCheckboxGroupProps) => (
  <Stack spacing="var(--zimm-scale-m)">
    {options.map((option) => (
      <ZimmCheckbox
        key={option.value}
        value={option.value}
        label={option.label}
        hitCount={option.hitCount}
        swatchColour={option.swatchColour}
        isChecked={selectedValues.includes(option.value)}
        onChange={onChange}
      />
    ))}
  </Stack>
);

